// Experience Quotients, version 2: complementary alignment.
// Counts, clocks, rates, score and reference answer: Briar M. Greenway (unchanged from version 1,
// and the same as Crushhh app/src/domain/quotients.ts).
// Overlay, complement and mirror lists: Briar M. Greenway, with role lists drafted by Claude and ratified by him.
// Complement, Accord, Spread, Together and the equal-weight rule: proposed by Claude (2026-10-25), under review.
var EQ = (function () {
  'use strict';
  // ---------- one person's counts ----------
  var REF = { years: 21, rel: 6, love: 3, hb: 2, longest: 4, partners: 24, perDay: 1, wkPeople: 3, wkOrg: 9 };
  var REF_RATE = {
    rel: REF.rel / REF.years, love: REF.love / REF.years, hb: REF.hb / REF.years,
    longest: REF.longest / REF.years, partners: REF.partners / REF.years,
    perDay: REF.perDay * 365, wkPeople: REF.wkPeople * 52, wkOrg: REF.wkOrg * 52
  };
  var REL = ['rel', 'love', 'hb', 'longest'], SEX = ['partners', 'perDay', 'wkPeople', 'wkOrg'];
  var LABEL = { rel: 'Relationships', love: 'Times in love', hb: 'Heartbreaks', longest: 'Longest relationship (share of the years)',
    partners: 'People slept with', perDay: 'Times a day you’d want', wkPeople: 'Different people a week', wkOrg: 'Orgasms a week' };
  function n(v) { v = Number(v); return isFinite(v) && v > 0 ? v : 0; }
  function yearsSince(age, start) {
    var since = typeof start === 'number' ? n(age) - n(start) : n(age);
    return Math.max(1, since);
  }
  function problems(q) {
    var out = [], age = n(q.age);
    if (q.age === null) out.push('Give your age.');
    else if (q.age < 18) out.push('This tool is for adults (18 and over).');
    if (q.firstRomantic === null) out.push('Say how old you were at your first relationship you chose, or tick Never.');
    if (q.firstSexual === null) out.push('Say how old you were at your first sexual experience you chose, or tick Never.');
    REL.concat(SEX).forEach(function (k) {
      if (q[k] === null) out.push('Answer every question (0 is an answer): ' + LABEL[k].toLowerCase() + '.');
      else if (q[k] < 0) out.push('No answer can be negative: ' + LABEL[k].toLowerCase() + '.');
    });
    if (typeof q.firstRomantic === 'number' && q.firstRomantic > age) out.push('Your first relationship cannot be after your current age.');
    if (typeof q.firstSexual === 'number' && q.firstSexual > age) out.push('Your first sexual experience cannot be after your current age.');
    if (q.firstRomantic === 'never' && (n(q.rel) > 0 || n(q.longest) > 0)) out.push('With no relationship yet, relationships and the longest one must be 0.');
    if (q.firstSexual === 'never' && n(q.partners) > 0) out.push('With no sexual experience, people slept with must be 0.');
    if (n(q.rel) === 0 && n(q.longest) > 0) out.push('A longest relationship needs at least one relationship.');
    if (typeof q.firstRomantic === 'number' && n(q.longest) > age - n(q.firstRomantic) + 0.5) out.push('Your longest relationship cannot be longer than the time since your first one began.');
    return out;
  }
  function reading(q) {
    var yRom = yearsSince(q.age, q.firstRomantic), ySex = yearsSince(q.age, q.firstSexual);
    var rate = {
      rel: n(q.rel) / yRom, love: n(q.love) / yRom, hb: n(q.hb) / yRom,
      longest: Math.min(n(q.longest), yRom) / yRom,
      partners: n(q.partners) / ySex,
      perDay: n(q.perDay) * 365, wkPeople: n(q.wkPeople) * 52, wkOrg: n(q.wkOrg) * 52
    };
    var score = {};
    Object.keys(rate).forEach(function (k) { score[k] = rate[k] <= 0 ? 0 : 100 * rate[k] / (rate[k] + REF_RATE[k]); });
    var mean = function (ks) { return ks.reduce(function (s, k) { return s + score[k]; }, 0) / ks.length; };
    var r = mean(REL), s = mean(SEX), top = Math.round(r), bottom = Math.round(s), gap = top - bottom;
    var tilt = gap >= 25 ? 'Strongly relational' : gap >= 10 ? 'Leans relational' : gap >= -9 ? 'Evenly balanced' : gap >= -24 ? 'Leans physical' : 'Strongly physical';
    return { reeq: top, seeq: bottom, rRaw: r, sRaw: s, eeq: Math.round((r + s) / 2), gap: gap, tilt: tilt, rate: rate, score: score, yRom: yRom, ySex: ySex };
  }

  // ---------- the overlay: experience and expectation for each role ----------
  var E_VAL = { never: 0, tried: 0.5, regularly: 1 };
  var X_VAL = { no: 0, curious: 0.5, yes: 1, notforme: 0 };
  var S_VAL = { no: 0, open: 0.5, yes: 1 };
  // [key, name, description, counterpart key, counterpart name, counterpart description]
  var PAIRS = {
    rel: [
      ['planner', 'Planner', 'Makes the plans and keeps things organised', 'free', 'Free spirit', 'Likes plans left open and goes with the flow'],
      ['caretaker', 'Caretaker', 'Looks after a partner’s comfort and needs', 'caredfor', 'Cared-for', 'Enjoys being looked after'],
      ['decider', 'Decider', 'Likes to make the call on shared choices', 'goalong', 'Go-along', 'Happy to let a partner decide'],
      ['initiator', 'Initiator', 'Starts affection and touch', 'receiver', 'Receiver', 'Enjoys affection and touch coming to them'],
      ['mentor', 'Mentor', 'Enjoys passing on what they know', 'learner', 'Learner', 'Enjoys learning from a partner'],
      ['talker', 'Talker', 'Does most of the talking and sharing', 'listener', 'Listener', 'Does most of the listening'],
      ['protector', 'Protector', 'Wants to keep a partner safe', 'protected', 'Protected', 'Feels good being kept safe'],
      ['adventurer', 'Adventurer', 'Pulls toward new places and plans', 'anchor', 'Anchor', 'Keeps things steady and grounded'],
      ['connector', 'Social connector', 'Brings people together; likes a full calendar', 'homebody', 'Homebody', 'Prefers time at home']
    ],
    sex: [
      ['dom', 'Dominant', 'Takes control in a scene', 'sub', 'Submissive', 'Hands control to a partner'],
      ['sadist', 'Sadist', 'Gives pain a partner has agreed to', 'maso', 'Masochist', 'Enjoys pain they have agreed to'],
      ['rigger', 'Rigger', 'Ties a partner up', 'ropebunny', 'Rope bunny', 'Enjoys being tied'],
      ['master', 'Master or Mistress', 'Holds authority that lasts beyond a scene', 'slave', 'Slave', 'Serves under authority that lasts beyond a scene'],
      ['owner', 'Owner', 'Keeps and cares for a partner in a pet role', 'pet', 'Pet', 'Takes on a pet role'],
      ['tamer', 'Brat tamer', 'Enjoys bringing a cheeky partner into line', 'brat', 'Brat', 'Enjoys pushing back playfully'],
      ['degrader', 'Degrader', 'Humiliates a partner who has asked for it', 'degradee', 'Degradee', 'Enjoys humiliation they have asked for'],
      ['caregiver', 'Daddy or Mommy', 'Plays a guiding, caring authority figure, between adults', 'little', 'Boy or Girl', 'Plays the one who is guided and cared for, between adults'],
      ['hunter', 'Primal hunter', 'Chases, catches and wrestles', 'prey', 'Primal prey', 'Enjoys being chased and caught'],
      ['exhib', 'Exhibitionist', 'Enjoys being watched', 'voyeur', 'Voyeur', 'Enjoys watching']
    ]
  };
  // Sexual styles that pair like with like (mirrors).
  var STYLE = [
    ['switch', 'Switch', 'Enjoys both sides of a dynamic'],
    ['experimental', 'Experimentalist', 'Likes to try new things'],
    ['vanilla', 'Vanilla', 'Prefers sex without kink'],
    ['ageplay', 'Ageplayer', 'Role-play between adults in which they act as other ages']
  ];
  // Relationship shapes that pair like with like (mirrors). Expectation only.
  var STRUCT = [
    ['mono', 'Monogamous', 'One partner, both ways'],
    ['open', 'Open or non-monogamous', 'More than one partner, openly'],
    ['live', 'Living together', ''],
    ['formal', 'Formal commitment', 'Marriage, civil partnership or the like'],
    ['kids', 'Children', 'Raising children together'],
    ['distance', 'Long distance', 'A relationship across a distance']
  ];
  var FLAG_STRUCT = { mono: true, kids: true };
  // Relationship expectation numbers, answered on ordered steps.
  var NUMBERS = [
    { key: 'days', label: 'Days a week together', options: ['0', '1', '2', '3', '4', '5', '6', '7'] },
    { key: 'length', label: 'How long you want your next relationship to last', options: ['A few months', 'About a year', 'A few years', 'Many years', 'For life'] },
    { key: 'atonce', label: 'Partners at once', options: ['1', '2', '3', '4 or more'] },
    { key: 'commit', label: 'Time before a commitment', options: ['Under a month', '1 to 3 months', '3 to 6 months', '6 to 12 months', 'Over a year', 'No commitment wanted'] }
  ];
  function roleList(side) {
    var out = [];
    PAIRS[side].forEach(function (p) { out.push([p[0], p[1], p[2]]); out.push([p[3], p[4], p[5]]); });
    if (side === 'sex') STYLE.forEach(function (s) { out.push(s); });
    return out;
  }
  function ev(P, k) { return E_VAL[P.roles[k].e]; }
  function xv(P, k) { return X_VAL[P.roles[k].x]; }
  function overlayProblems(P) {
    var out = [];
    ['rel', 'sex'].forEach(function (side) {
      var missing = roleList(side).filter(function (r) { var a = P.roles[r[0]]; return !a || !a.e || !a.x; }).length;
      if (missing) out.push((side === 'rel' ? 'Relationship' : 'Sexual') + ' roles: ' + missing + ' not answered yet.');
    });
    var s = STRUCT.filter(function (r) { return !P.struct[r[0]]; }).length;
    if (s) out.push('Relationship shape: ' + s + ' not answered yet.');
    var m = NUMBERS.filter(function (x) { return P.numbers[x.key] === null || P.numbers[x.key] === undefined; }).length;
    if (m) out.push('Relationship numbers: ' + m + ' not answered yet.');
    return out;
  }
  // A person's two double numbers. Experience weighs the counts and the overlay equally;
  // expectation is the overlay alone.
  function doubles(P, rd) {
    function side(s, countScore) {
      var rs = roleList(s);
      var e = rs.reduce(function (t, r) { return t + ev(P, r[0]); }, 0) / rs.length;
      var x = rs.reduce(function (t, r) { return t + xv(P, r[0]); }, 0) / rs.length;
      return { experience: Math.round((countScore + 100 * e) / 2), expectation: Math.round(100 * x) };
    }
    return { rel: side('rel', rd.rRaw), sex: side('sex', rd.sRaw) };
  }

  // ---------- two people ----------
  var TOL = {
    strict: 1,
    middle: 1 / Math.sqrt(2 * Math.log(1 / 0.8)),
    loose: 1 / Math.sqrt(2 * Math.log(1 / 0.9))
  };
  // Appetite: compare two wanted rates by how many doublings apart they are.
  function appetiteFit(a, b, T) {
    a = n(a); b = n(b);
    if (a === 0 && b === 0) return 1;
    if (a === 0 || b === 0) return 0;
    var d = Math.abs(Math.log(a / b)) / Math.LN2;
    return Math.exp(-(d * d) / (2 * T * T));
  }
  function entropy(masses) {
    var t = masses.reduce(function (s, m) { return s + m; }, 0), h = 0;
    masses.forEach(function (m) { if (m > 0) { var p = m / t; h -= p * Math.log(p); } });
    return h;
  }
  function sum(xs, f) { return xs.reduce(function (s, x) { return s + f(x); }, 0); }
  function ratio(a, b) { return b > 0 ? a / b : null; }
  function perDayText(yearly) { return (Math.round(n(yearly) / 365 * 100) / 100) + ' a day'; }
  function mean(xs) { return xs.length ? xs.reduce(function (s, x) { return s + x; }, 0) / xs.length : null; }

  function couple(A, B, ra, rb, tolKey) {
    var T = TOL[tolKey || 'middle'];
    var dirs = [], bounds = [];
    ['rel', 'sex'].forEach(function (side) {
      PAIRS[side].forEach(function (pr, i) {
        [[A, B, 'A', 'B'], [B, A, 'B', 'A']].forEach(function (o) {
          var P = o[0], Q = o[1], p = pr[0], q = pr[3];
          var xp = xv(P, p), xq = xv(Q, q), ep = ev(P, p), eq = ev(Q, q);
          var rp = Math.max(0, xp - ep), rq = Math.max(0, xq - eq);
          dirs.push({ side: side, pair: i, first: o[2], met: xp * xq, sought: Math.max(xp, xq),
            supply: ep * xp * rq + eq * xq * rp, reach: rp + rq });
          if (P.roles[p].x === 'notforme' && xq >= 0.5) bounds.push(o[3] + ' wants to be ' + pr[4] + ' with a ' + pr[1] + '; ' + o[2] + ' has ruled out being ' + pr[1] + '.');
          if (Q.roles[q].x === 'notforme' && xp >= 0.5) bounds.push(o[2] + ' wants to be ' + pr[1] + ' with a ' + pr[4] + '; ' + o[3] + ' has ruled out being ' + pr[4] + '.');
        });
      });
    });
    function cSide(f) {
      var ds = dirs.filter(f);
      return { C: ratio(sum(ds, function (d) { return d.met; }), sum(ds, function (d) { return d.sought; })),
        L: ratio(sum(ds, function (d) { return d.supply; }), sum(ds, function (d) { return d.reach; })) };
    }
    var all = cSide(function () { return true; });
    var bySide = { rel: cSide(function (d) { return d.side === 'rel'; }), sex: cSide(function (d) { return d.side === 'sex'; }) };

    // Spread: the met wishes form a cascade, couple → sides → pairs → directions. At each level,
    // evenness is how evenly each branch's share splits among its own children (Shannon entropy over
    // its maximum, Pielou's evenness), averaged over the branches by their share. Spread is the mean
    // of the three levels: 1 when every split is even, 0 when every split goes one way.
    var met = function (f) { return sum(dirs.filter(f), function (d) { return d.met; }); };
    var total = met(function () { return true; }), Dk = null, S = null;
    function evenness(children) { return entropy(children) / Math.log(children.length); }
    if (total > 0) {
      // The two sides are equal halves of a couple (as in Accord), so each side's share is its met
      // wishes per direction it has room for: 9 relationship pairs and 10 sexual pairs count alike.
      var sideMass = ['rel', 'sex'].map(function (s) { return met(function (d) { return d.side === s; }); });
      var sideRoom = ['rel', 'sex'].map(function (s) { return 2 * PAIRS[s].length; });
      var dens = sideMass.map(function (m, i) { return m / sideRoom[i]; });
      var densTotal = dens[0] + dens[1];
      var d1 = evenness(dens), d2 = 0, d3 = 0;
      ['rel', 'sex'].forEach(function (s, si) {
        if (sideMass[si] === 0) return;
        var share = dens[si] / densTotal;
        var pairMass = PAIRS[s].map(function (_, i) { return met(function (d) { return d.side === s && d.pair === i; }); });
        d2 += share * evenness(pairMass);
        pairMass.forEach(function (pm, i) {
          if (pm === 0) return;
          var two = dirs.filter(function (d) { return d.side === s && d.pair === i; }).map(function (d) { return d.met; });
          d3 += share * (pm / sideMass[si]) * evenness(two);
        });
      });
      Dk = [d1, d2, d3];
      S = mean(Dk);
    }

    // Accord on the mirrors.
    var acc = { rel: [], sex: [] }, rows = [];
    STRUCT.forEach(function (r) {
      var a = S_VAL[A.struct[r[0]]], b = S_VAL[B.struct[r[0]]], v = 1 - Math.abs(a - b);
      acc.rel.push(v); rows.push({ side: 'rel', label: r[1], a: A.struct[r[0]], b: B.struct[r[0]], v: v });
      if (FLAG_STRUCT[r[0]] && Math.abs(a - b) === 1) bounds.push(r[1] + ': one of you said yes and the other no.');
    });
    NUMBERS.forEach(function (x) {
      var ia = A.numbers[x.key], ib = B.numbers[x.key], v = 1 - Math.abs(ia - ib) / (x.options.length - 1);
      acc.rel.push(v); rows.push({ side: 'rel', label: x.label, a: x.options[ia], b: x.options[ib], v: v });
    });
    STYLE.forEach(function (r) {
      var a = xv(A, r[0]), b = xv(B, r[0]), v = 1 - Math.abs(a - b);
      acc.sex.push(v); rows.push({ side: 'sex', label: r[1], a: A.roles[r[0]].x, b: B.roles[r[0]].x, v: v });
      var ra_ = A.roles[r[0]].x, rb_ = B.roles[r[0]].x;
      if ((ra_ === 'notforme' && rb_ === 'yes') || (rb_ === 'notforme' && ra_ === 'yes')) bounds.push(r[1] + ': one of you wants it and the other has ruled it out.');
    });
    var ap = appetiteFit(ra.rate.perDay, rb.rate.perDay, T);
    acc.sex.push(ap); rows.push({ side: 'sex', label: 'How often you’d want sex', a: perDayText(ra.rate.perDay), b: perDayText(rb.rate.perDay), v: ap });
    var accRel = mean(acc.rel), accSex = mean(acc.sex), Acc = (accRel + accSex) / 2;

    var together = all.C === null ? null : 100 * Math.sqrt(all.C * Acc) * (1 + (S === null ? 0 : S)) / 2;
    return { C: all.C, L: all.L, A: Acc, S: S, Dk: Dk, together: together,
      sides: { rel: { C: bySide.rel.C, L: bySide.rel.L, A: accRel }, sex: { C: bySide.sex.C, L: bySide.sex.L, A: accSex } },
      dirs: dirs, accord: rows, boundaries: bounds };
  }
  return { REF_RATE: REF_RATE, LABEL: LABEL, REL: REL, SEX: SEX, problems: problems, reading: reading, TOL: TOL,
    PAIRS: PAIRS, STYLE: STYLE, STRUCT: STRUCT, NUMBERS: NUMBERS, roleList: roleList,
    overlayProblems: overlayProblems, doubles: doubles, couple: couple, appetiteFit: appetiteFit, entropy: entropy };
})();
if (typeof module !== 'undefined') module.exports = EQ;
